    # A vertical 5-line extends the adjacent colored tile along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5 or (r > 0 and grid[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == 5:
                end += 1
            if c + 1 < w and grid[end][c + 1] not in (0, 5):
                x = c + 1
                while x < w and grid[end][x] not in (0, 5):
                    x += 1
                width = x - c - 1
                tile = []
                y = end
                while y >= r and all(grid[y][xx] not in (0, 5) for xx in range(c + 1, x)):
                    tile.append(grid[y][c + 1:x])
                    y -= 1
                if tile:
                    for yy in range(r, end + 1):
                        values = tile[(end - yy) % len(tile)]
                        out[yy][c + 1:x] = values[:]
            r = end + 1

    # A horizontal 5-line extends a vertical colored tile from its left end.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5 or (c > 0 and grid[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and grid[r][end + 1] == 5:
                end += 1
            if r + 1 < h and grid[r + 1][c] not in (0, 5):
                y = r + 1
                while y < h and grid[y][c] not in (0, 5):
                    y += 1
                tile = [grid[yy][c] for yy in range(r + 1, y)]
                for xx in range(c, end + 1):
                    for offset, value in enumerate(tile):
                        out[r + 1 + offset][xx] = value
            c = end + 1
    return out
